def glossary_terms(md):
    out = []
    for line in md.split('\n'):
        if not line.startswith('| **'): continue
        cells = [c.strip() for c in line.strip('|').split('|')]
        term = cells[0].replace('**', '').strip()
        exp, mean = cells[1], cells[2]
        title = term + (' — ' + exp if exp else '')
        aliases = re.split(r'\s+/\s+|,\s*', term)
        aliases = [a.strip() for a in aliases if a.strip()]
        # «Synergies», «Teaser» и т.п. — английские слова в тексте почти не встречаются; оставляем
        pats = []
        for a in aliases:
            if re.match(r'^[A-Za-zА-ЯЁ&/()0-9 .-]+$', a):
                pats.append(re.escape(a).replace('\\ ', ' '))
        if pats:
            out.append((pats, title, mean))
    return out

def build(glossary_md):
    seen = set(); terms = []
    for pats, title, d in RICH + EXTRA + glossary_terms(glossary_md):
        key = pats[0].lower()
        if key in seen: continue
        seen.add(key)
        terms.append({'p': pats, 't': title, 'd': d})
    return terms
